"use client";

import { useEffect, useState } from "react";
import { site } from "@/lib/site";

const formatter = new Intl.DateTimeFormat("en-US", {
  hour: "2-digit",
  minute: "2-digit",
  second: "2-digit",
  hourCycle: "h23",
  timeZone: site.timezone,
  timeZoneName: "short",
});

/**
 * Live local clock in Dhruv's timezone — quiet "this person is
 * shipping right now" signal. Mount-only render to avoid timezone mismatch.
 */
export function LocalTime() {
  const [label, setLabel] = useState<string | null>(null);

  useEffect(() => {
    const update = () => setLabel(formatter.format(new Date()));
    update();
    const id = window.setInterval(update, 1000);
    return () => window.clearInterval(id);
  }, []);

  return (
    <span className="tabular-nums" aria-label={`Local time in ${site.city}`}>
      {label ?? "--:--:--"}
    </span>
  );
}

import { site } from "@/lib/site";

/**
 * Command menu model — the full list of actions a Visitor can run.
 * Pure data + filtering so behavior stays testable.
 */
export type CommandGroup = "Navigate" | "Actions" | "Socials";

export type CommandAction =
  | { type: "navigate"; href: string; external?: boolean }
  | { type: "copy"; text: string; doneLabel: string }
  | { type: "theme" };

export type CommandItem = {
  id: string;
  group: CommandGroup;
  label: string;
  keywords: string[];
  /** Right-side hint rendered in the row (e.g. "↵", "⌘L"). */
  hint?: string;
  action: CommandAction;
};

export const GROUP_ORDER: readonly CommandGroup[] = [
  "Navigate",
  "Actions",
  "Socials",
] as const;

const EMAIL = "Dhruv2mars@gmail.com";

/** Dark-state drives only the theme-toggle label. */
export function buildCommands(options: { isDark: boolean }): CommandItem[] {
  const items: CommandItem[] = [
    {
      id: "home",
      group: "Navigate",
      label: "Home",
      keywords: ["index", "start"],
      hint: "H",
      action: { type: "navigate", href: "/" },
    },
    {
      id: "writings",
      group: "Navigate",
      label: "Writings",
      keywords: ["blog", "posts", "essays", "writing"],
      hint: "W",
      action: { type: "navigate", href: "/writings" },
    },
    {
      id: "projects",
      group: "Navigate",
      label: "Projects",
      keywords: ["work", "repos", "code"],
      hint: "P",
      action: { type: "navigate", href: "/projects" },
    },
    {
      id: "rss",
      group: "Navigate",
      label: "RSS feed",
      keywords: ["feed", "subscribe", "xml", "atom"],
      action: { type: "navigate", href: site.rssPath, external: true },
    },
    {
      id: "copy-email",
      group: "Actions",
      label: "Copy email address",
      keywords: ["email", "mail", "contact", "copy", "reach"],
      hint: "⌘E",
      action: { type: "copy", text: EMAIL, doneLabel: "Email copied" },
    },
    {
      id: "theme",
      group: "Actions",
      label: options.isDark ? "Switch to light theme" : "Switch to dark theme",
      keywords: ["theme", "dark", "light", "mode", "appearance", "toggle"],
      hint: "⌘L",
      action: { type: "theme" },
    },
    {
      id: "source",
      group: "Actions",
      label: "View source",
      keywords: ["github", "code", "source", "repo"],
      action: {
        type: "navigate",
        href: "https://github.com/Dhruv2mars/portfolio",
        external: true,
      },
    },
  ];

  for (const social of site.socials) {
    if (social.label === "Email") continue;
    items.push({
      id: `social-${social.label.toLowerCase()}`,
      group: "Socials",
      label: social.label,
      keywords: ["social", "external", "link", social.label.toLowerCase()],
      action: { type: "navigate", href: social.href, external: true },
    });
  }

  return items;
}

function normalize(query: string): string {
  return query.trim().toLowerCase();
}

/** Case-insensitive substring match over label + keywords. Order preserved. */
export function filterCommands(
  items: readonly CommandItem[],
  query: string,
): CommandItem[] {
  const q = normalize(query);
  if (!q) return [...items];

  return items.filter((item) => {
    if (item.label.toLowerCase().includes(q)) return true;
    return item.keywords.some((k) => k.includes(q));
  });
}

/** Flatten into renderable blocks of [group, items[]], dropping empty groups. */
export function groupCommands(
  items: readonly CommandItem[],
): { group: CommandGroup; items: CommandItem[] }[] {
  return GROUP_ORDER.map((group) => ({
    group,
    items: items.filter((i) => i.group === group),
  })).filter(({ items: groupItems }) => groupItems.length > 0);
}

import { describe, expect, test } from "bun:test";
import {
  buildCommands,
  filterCommands,
  groupCommands,
} from "@/lib/commands";

describe("buildCommands", () => {
  test("covers all three pages plus the core actions", () => {
    const items = buildCommands({ isDark: false });
    const ids = items.map((i) => i.id);
    expect(ids).toContain("home");
    expect(ids).toContain("writings");
    expect(ids).toContain("projects");
    expect(ids).toContain("copy-email");
    expect(ids).toContain("theme");
    expect(ids).toContain("source");
  });

  test("theme label flips with current theme", () => {
    const dark = buildCommands({ isDark: true }).find((i) => i.id === "theme");
    const light = buildCommands({ isDark: false }).find(
      (i) => i.id === "theme",
    );
    expect(dark?.label).toBe("Switch to light theme");
    expect(light?.label).toBe("Switch to dark theme");
  });

  test("mail-to email social is excluded — copy action owns Email", () => {
    const items = buildCommands({ isDark: false });
    expect(
      items.filter((i) => i.group === "Socials").map((i) => i.label),
    ).not.toContain("Email");
    const copy = items.find((i) => i.id === "copy-email");
    expect(copy?.action).toEqual({
      type: "copy",
      text: "Dhruv2mars@gmail.com",
      doneLabel: "Email copied",
    });
  });

  test("navigate items carry hrefs", () => {
    const items = buildCommands({ isDark: false });
    for (const item of items) {
      if (item.action.type === "navigate") {
        expect(item.action.href.length).toBeGreaterThan(0);
      }
    }
  });
});

describe("filterCommands", () => {
  const items = buildCommands({ isDark: false });

  test("empty query returns everything", () => {
    expect(filterCommands(items, "")).toHaveLength(items.length);
    expect(filterCommands(items, "   ")).toHaveLength(items.length);
  });

  test("matches by label, case-insensitive", () => {
    const out = filterCommands(items, "WRITINGS");
    expect(out.map((i) => i.id)).toEqual(["writings"]);
  });

  test("matches by keyword", () => {
    const out = filterCommands(items, "dark");
    expect(out.map((i) => i.id)).toContain("theme");
  });

  test("unknown query yields no items", () => {
    expect(filterCommands(items, "xylophone")).toHaveLength(0);
  });
});

describe("groupCommands", () => {
  test("groups in stable order and drops empty groups", () => {
    const items = buildCommands({ isDark: false });
    const groups = groupCommands(items);
    expect(groups.map((g) => g.group)).toEqual([
      "Navigate",
      "Actions",
      "Socials",
    ]);

    const onlyProjects = filterCommands(items, "projects");
    const filtered = groupCommands(onlyProjects);
    expect(filtered).toHaveLength(1);
    expect(filtered[0]!.group).toBe("Navigate");
  });
});

/**
 * Command menu open-state — module-level pub/sub so the header trigger
 * and the mounted menu share one store without a context tree.
 */
let open = false;
const listeners = new Set<() => void>();

function emit() {
  for (const listener of listeners) listener();
}

export function setCommandMenuOpen(value: boolean) {
  if (open === value) return;
  open = value;
  emit();
}

export function toggleCommandMenu() {
  setCommandMenuOpen(!open);
}

export function subscribeCommandMenu(callback: () => void): () => void {
  listeners.add(callback);
  return () => {
    listeners.delete(callback);
  };
}

export function getCommandMenuOpen(): boolean {
  return open;
}

"use client";

import { useRouter } from "next/navigation";
import { useTheme } from "next-themes";
import {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
  useSyncExternalStore,
} from "react";
import {
  buildCommands,
  filterCommands,
  groupCommands,
  type CommandItem,
} from "@/lib/commands";
import {
  getCommandMenuOpen,
  setCommandMenuOpen,
  subscribeCommandMenu,
  toggleCommandMenu,
} from "@/lib/command-menu-store";

export function useCommandMenuOpen(): boolean {
  return useSyncExternalStore(
    subscribeCommandMenu,
    getCommandMenuOpen,
    () => false,
  );
}

function isEditableTarget(target: EventTarget | null): boolean {
  if (!(target instanceof HTMLElement)) return false;
  return (
    target instanceof HTMLInputElement ||
    target instanceof HTMLTextAreaElement ||
    target instanceof HTMLSelectElement ||
    target.isContentEditable
  );
}

/**
 * Command menu — ⌘K. One honest answer to "where do I go next".
 * Listbox semantics; arrows cycle, Enter runs, Esc closes.
 */
export function CommandMenu() {
  const open = useCommandMenuOpen();
  const router = useRouter();
  const { resolvedTheme, setTheme } = useTheme();
  const isDark = resolvedTheme === "dark";

  const [query, setQuery] = useState("");
  const [activeId, setActiveId] = useState<string | null>(null);
  const [status, setStatus] = useState<string | null>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const listRef = useRef<HTMLDivElement>(null);

  const items = useMemo(() => buildCommands({ isDark }), [isDark]);
  const filtered = useMemo(() => filterCommands(items, query), [items, query]);
  const groups = useMemo(() => groupCommands(filtered), [filtered]);

  const close = useCallback(() => {
    setCommandMenuOpen(false);
    setQuery("");
    setStatus(null);
    setActiveId(null);
  }, []);

  // Global ⌘K / Ctrl+K — open/close from anywhere.
  useEffect(() => {
    const onKeydown = (event: KeyboardEvent) => {
      if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === "k") {
        event.preventDefault();
        toggleCommandMenu();
      }
    };
    window.addEventListener("keydown", onKeydown);
    return () => window.removeEventListener("keydown", onKeydown);
  }, []);

  // Focus input + lock scroll while open.
  useEffect(() => {
    if (!open) return;
    const frame = requestAnimationFrame(() => inputRef.current?.focus());
    const previous = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => {
      cancelAnimationFrame(frame);
      document.body.style.overflow = previous;
    };
  }, [open]);

  // Reset selection when the list changes.
  useEffect(() => {
    setActiveId((current) =>
      current && filtered.some((i) => i.id === current)
        ? current
        : (filtered[0]?.id ?? null),
    );
  }, [filtered]);

  // Keep the active option in view while arrowing.
  useEffect(() => {
    if (!activeId || !listRef.current) return;
    listRef.current
      .querySelector(`[data-command-id="${activeId}"]`)
      ?.scrollIntoView({ block: "nearest" });
  }, [activeId]);

  const run = useCallback(
    (item: CommandItem) => {
      switch (item.action.type) {
        case "navigate": {
          const href = item.action.href;
          close();
          if (item.action.external) {
            window.open(href, "_blank", "noopener,noreferrer");
          } else {
            router.push(href);
          }
          return;
        }
        case "copy": {
          void navigator.clipboard
            .writeText(item.action.text)
            .then(() => {
              setStatus(item.action.type === "copy" ? item.action.doneLabel : null);
              window.setTimeout(close, 700);
            })
            .catch(() => {
              setStatus("Copy failed — blocked by browser");
              window.setTimeout(close, 1200);
            });
          return;
        }
        case "theme": {
          setTheme(isDark ? "light" : "dark");
          setStatus(isDark ? "Light theme on" : "Dark theme on");
          window.setTimeout(close, 450);
          return;
        }
      }
    },
    [close, isDark, router, setTheme],
  );

  const onKeydown = (event: React.KeyboardEvent) => {
    if (event.key === "Escape") {
      event.preventDefault();
      close();
      return;
    }
    if (event.key === "ArrowDown" || event.key === "ArrowUp") {
      event.preventDefault();
      if (filtered.length === 0) return;
      const index = filtered.findIndex((i) => i.id === activeId);
      const delta = event.key === "ArrowDown" ? 1 : -1;
      const next =
        filtered[(index + delta + filtered.length) % filtered.length];
      setActiveId(next?.id ?? null);
      return;
    }
    if (event.key === "Enter") {
      event.preventDefault();
      const item = filtered.find((i) => i.id === activeId) ?? filtered[0];
      if (item) run(item);
    }
  };

  if (!open) return null;

  return (
    <div
      role="dialog"
      aria-modal="true"
      aria-label="Command menu"
      className="command-overlay"
      onMouseDown={(event) => {
        if (event.target === event.currentTarget) close();
      }}
    >
      <div className="command-panel" onKeyDown={onKeydown}>
        <div className="flex items-center gap-2 border-b border-border px-4">
          <input
            ref={inputRef}
            value={query}
            onChange={(event) => setQuery(event.target.value)}
            placeholder="Go anywhere…"
            aria-label="Search commands"
            className="h-12 w-full bg-transparent text-[14px] text-foreground outline-none placeholder:text-faint"
          />
          <kbd className="kbd">esc</kbd>
        </div>

        <div
          ref={listRef}
          role="listbox"
          aria-activedescendant={activeId ?? undefined}
          className="max-h-[19rem] overflow-y-auto px-2 py-2 [-ms-overflow-style:none] [scrollbar-width:none] [&::-webkit-scrollbar]:hidden"
        >
          {groups.length === 0 ? (
            <p className="px-3 py-6 text-[13px] text-faint">
              Nothing matches “{query}”.
            </p>
          ) : (
            groups.map(({ group, items: groupItems }) => (
              <div key={group} className="pb-1">
                <p className="px-3 pt-2 pb-1 text-[10px] font-medium uppercase tracking-[0.16em] text-faint">
                  {group}
                </p>
                {groupItems.map((item) => {
                  const active = item.id === activeId;
                  return (
                    <button
                      key={item.id}
                      type="button"
                      role="option"
                      id={`command-${item.id}`}
                      aria-selected={active}
                      data-command-id={item.id}
                      onMouseMove={() => {
                        if (!active) setActiveId(item.id);
                      }}
                      onClick={() => run(item)}
                      className={`command-row ${active ? "command-row-active" : ""}`}
                    >
                      <span className="truncate">{item.label}</span>
                      {active ? (
                        <kbd className="kbd shrink-0" aria-hidden>
                          ↵
                        </kbd>
                      ) : null}
                    </button>
                  );
                })}
              </div>
            ))
          )}
        </div>

        <div className="flex items-center justify-between border-t border-border px-4 py-2.5">
          <p className="meta-copy" aria-live="polite">
            {status ?? `${filtered.length} ${filtered.length === 1 ? "command" : "commands"}`}
          </p>
          <p className="meta-copy" aria-hidden>
            ↑↓ navigate
          </p>
        </div>
      </div>
    </div>
  );
}

